from pathlib import Path
import json,html,shutil,hashlib
import argparse
parser=argparse.ArgumentParser(description='Build a local comparison preview; never publishes media')
parser.add_argument('--run',type=Path,required=True);parser.add_argument('--out',type=Path,required=True)
args=parser.parse_args();R=args.run;O=args.out;O.mkdir(parents=True,exist_ok=True);
d=json.loads((R/'results.json').read_text());sources={x['style_id']:x for x in json.loads((R/'source_assignments.json').read_text())['assignments']}
e=lambda x:html.escape(str(x),quote=True)
names={'native':'Codex 内置生图','web':'ChatGPT 网页内置生图','tie':'平局','missing':'缺少配对'}
def text(v):
 if isinstance(v,dict):return '；'.join(str(k)+'：'+text(w) for k,w in v.items())
 if isinstance(v,list):return '；'.join(text(w) for w in v)
 return str(v)
articles=[];checks=[]
for n,p in enumerate(d['pairs'],1):
 sid=p['case_id'];complete=p['complete_image_pair'];winner=p['rendering_winner'] if complete else 'missing';imgs=[]
 for side,route in p['mapping'].items():
  src=R/'blind'/sid/(side+'.png');dest=O/'images'/sid/(side+'.png')
  if src.exists():
   dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dest);checks.append({'file':str(dest.relative_to(O)),'sha256':hashlib.sha256(dest.read_bytes()).hexdigest()});body=f'<a href="images/{sid}/{side}.png" target="_blank" rel="noopener"><img loading="lazy" src="images/{sid}/{side}.png" alt="{e(p["style_label"])} 候选 {side}"></a>'
  else:
   st=p['candidate_status'][route];body='<div class="missing">'+('请求明确失败' if st.get('failed') else '未取得可核验原图')+'<small>不补图，不计为平局</small></div>'
  imgs.append(f'<figure><figcaption><b>{side}</b><span class="reveal">{names[route]}</span></figcaption>{body}<small>AI 生成 · '+('1024 × 1536 · 点击查看原图' if src.exists() else '无原文件')+'</small></figure>')
 details=[]
 for j,r in enumerate(p.get('reviews',[]),1):
  if r is None: continue
  chunks=[]
  for key,title in [('rendering_reason','渲染与合成'),('style_reason','风格表达'),('product_notes','商品保真'),('identity_notes','身份保真')]:
   chunks.append(f'<h4>{title}</h4><p>{e(text(r.get(key,"未记录")))}</p>')
  details.append(f'<details><summary>评审 {j} · 渲染投票：{e(r.get("rendering_vote","未记录"))}</summary>'+''.join(chunks)+'</details>')
 dims=''.join(f'<span>{title}：{names.get(p.get(key),"未评") if complete else "未评"}</span>' for key,title in [('rendering_winner','渲染'),('style_winner','风格'),('product_winner','商品'),('identity_winner','身份')])
 s=sources[sid];url=s.get('source_page','');credit=f'<a href="{e(url)}" target="_blank" rel="noopener">服饰参考来源</a> · {e(s.get("author","未记录"))} · {e(s.get("license","待核实"))}' if url.startswith('https://') else '服饰参考来源待整理'
 articles.append(f'<article id="{sid}" data-result="{winner}" data-search="{e(p["style_label"].lower())}"><header><div><small>STYLE {n:02d}</small><h2>{e(p["style_label"])}</h2></div><span class="badge reveal">{names.get(winner,"未评")}{" · 本组渲染偏好" if complete and winner!="tie" else ""}</span></header><div class="pair">'+''.join(imgs)+f'</div><div class="dims reveal">{dims}</div><div class="review reveal">'+''.join(details)+f'</div><p class="credit">{credit}<br>来源记录不等于公开使用许可已通过；身份参考与衍生图的公开范围仍待核实。</p></article>')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f3ee;color:#202723;font:16px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:#255b4e}button,input,select{font:inherit}button,select,input{padding:10px 14px;border:1px solid #a9b5ac;border-radius:6px;background:#fff;color:#202723}button{cursor:pointer}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #ba6525;outline-offset:3px}.wrap{max-width:1180px;margin:auto;padding:0 24px}.notice{background:#244a3f;color:#fff;padding:12px 24px;font-size:14px;text-align:center}.hero{padding:60px 0 35px}.eyebrow{letter-spacing:2px;font-size:12px;color:#52675c}h1{font-size:clamp(32px,5vw,60px);letter-spacing:-2px;line-height:1.15;margin:16px 0 22px}h1 span{color:#486b5a}p{max-width:900px}.lead{font-size:20px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:30px 0}.stat{padding:20px;background:#fff;border:1px solid #dddcd5}.stat strong{font-size:34px;display:block}.stat small{color:#56665e}.method{background:#e7ece5;padding:22px;border-left:3px solid #486b5a}table{width:100%;border-collapse:collapse;margin:22px 0}th,td{text-align:left;padding:12px;border-bottom:1px solid #cccfc7}.tools{position:sticky;top:0;z-index:2;background:#f5f3eef5;padding:16px 0;display:flex;flex-wrap:wrap;gap:10px;align-items:center}input{flex:1;min-width:170px}.count{font-size:13px;color:#536358}article{background:#fff;border:1px solid #d9ddd6;margin:0 0 30px;padding:24px;scroll-margin-top:100px}article header{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:18px}h2{font-size:22px;margin:4px 0}header small{font-size:11px;letter-spacing:2px;color:#65766b}.badge{font-size:12px;padding:6px 10px;background:#e9eee7;white-space:nowrap}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0;min-width:0}figcaption{display:flex;align-items:center;gap:12px;margin:0 0 8px}figcaption b{font-size:22px}figure img{display:block;width:100%;height:auto;background:#efefeb}figure small{font-size:12px;color:#626d64}.missing{aspect-ratio:2/3;background:#f0f1ec;display:flex;flex-direction:column;justify-content:center;align-items:center;border:1px dashed #aab3a6;text-align:center;padding:12px}.missing small{margin-top:10px}.dims{display:flex;gap:8px 24px;flex-wrap:wrap;padding:16px 0;font-size:14px}.review{border-top:1px solid #e5e7e1}details{border-bottom:1px solid #e5e7e1;padding:12px 0}summary{cursor:pointer;font-weight:600}h4{margin:18px 0 3px}details p{font-size:14px;margin:4px 0 12px}.credit{color:#687267;font-size:12px;margin-bottom:0}footer{padding:24px 0 60px;font-size:14px;color:#56645c}.blind .reveal,.blind .hero,.blind #filter{display:none}.hidden{display:none!important}@media(max-width:640px){.wrap{padding:0 12px}.hero{padding-top:30px}.stats{grid-template-columns:1fr 1fr}.stat{padding:12px}article{padding:12px}.pair{gap:8px}article header{display:block}.badge{display:inline-block;margin-top:8px}h2{font-size:18px}.lead{font-size:17px}.tools{position:static}figcaption{font-size:12px;gap:7px}.method{padding:14px}th,td{padding:8px 4px;font-size:13px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>24 风格 · Codex 与 ChatGPT 生图对照</title><style>'''+css+'''</style></head><body><div class="notice">本地审阅稿 · 尚未上传 GitHub · 图片均为 AI 生成 · 公开使用范围待核实</div><main class="wrap"><section class="hero"><div class="eyebrow">THREADTRUTH STUDIO / ENTRY COMPARISON</div><h1>同一组参考，<br><span>两个生图入口。</span></h1><p class="lead">24 种服装人像风格，比较光影、材质与场景融合。<br>保留全部已保存结果，让图片和可见依据一起说话。</p><div class="stats"><div class="stat"><strong>24</strong><small>风格 · 每端各请求一次</small></div><div class="stat"><strong>43 / 48</strong><small>已保存原图 / 请求数</small></div><div class="stat"><strong>19</strong><small>完整配对 · 另有 5 组缺图</small></div><div class="stat"><strong>11 : 7 : 1</strong><small>网页胜 / Codex 胜 / 平局</small></div></div><div class="method"><b>本轮网页获得更多渲染偏好，具体表现随风格变化。</b><p>每风格每端只有一张，不能据此推断稳定胜率。三个隔离上下文重复盲评，至少两票同向才判胜；不宣称评审统计独立或统计显著性。实际生图型号未核实，结果不能归因于“2.5”。</p><p>主评：光影与体积、皮肤和材质自然度、衣服贴合与褶皱受力、空间融合、摄影完成度。保真另评；姿态不同或像素变化本身不构成渲染失败。</p></div><table><caption>四个维度独立统计 · 分母均为 19 组</caption><thead><tr><th>评审维度</th><th>Codex 胜</th><th>网页胜</th><th>平局</th></tr></thead><tbody>'''+''.join(f'<tr><td>{title}</td><td>{d["totals"][key]["native"]}</td><td>{d["totals"][key]["web"]}</td><td>{d["totals"][key]["tie"]}</td></tr>' for key,title in [('rendering','渲染与合成'),('style','风格表达'),('product','商品保真'),('identity','身份保真')])+'''</tbody></table><p>建议：优先渲染时可参考网页的本轮结果，也应查看各风格对照。Skill 默认仍为 Codex，用户手选优先。这次比较不是 beta.6 六图完整流程的效果验收。</p></section><div class="tools"><label for="query">找风格</label><input id="query" placeholder="例如：通勤 / old money"><select id="filter" aria-label="按渲染结果筛选"><option value="all">全部 24 个风格</option><option value="web">网页偏好 · 11</option><option value="native">Codex 偏好 · 7</option><option value="tie">平局 · 1</option><option value="missing">缺少配对 · 5</option></select><button id="blind" aria-pressed="false">隐藏来源与结论</button><span id="count" class="count" aria-live="polite">显示 24 个风格</span></div><div id="gallery">'''+''.join(articles)+'''</div><footer><h2>如何理解这轮测试</h2><p>两端使用同组冻结参考与提示词，每次独立生成、仅用内置生图；全部原图为 1024 × 1536 PNG，展示文件与已保存原图逐字节一致，未裁切、锐化或修图。A/B 顺序沿用原盲评映射。隐藏来源仅供自行观看，不构成新的正式盲评。</p><p>Codex 保存 21/24，网页保存 22/24。缺图涉及执行、登录、网络或结果取回状态，不能归因于模型可靠性。部分配对因失败和上传等待偏离原定先后顺序；本轮不是完全同步的受控实验。耗时不计入画质评分。</p><p>本页是待审展示稿。服饰来源及身份参考的公开使用范围尚待核实，原参考图、私人对话链接和执行日志未随本页提供。没有上传 GitHub，也没有更改历史公开图库。</p><a href="#">返回顶部 ↑</a></footer></main><script>const q=document.querySelector('#query'),f=document.querySelector('#filter'),b=document.querySelector('#blind'),cards=[...document.querySelectorAll('article')];function normalize(s){return s.toLowerCase().trim().replace(/[\\s-]+/g,' ')}function filter(){let n=0;for(const c of cards){const ok=(f.value==='all'||c.dataset.result===f.value)&&normalize(c.dataset.search+' '+c.id).includes(normalize(q.value));c.classList.toggle('hidden',!ok);if(ok)n++}document.querySelector('#count').textContent='显示 '+n+' 个风格'}q.addEventListener('input',filter);f.addEventListener('change',filter);b.addEventListener('click',()=>{const on=document.body.classList.toggle('blind');b.setAttribute('aria-pressed',String(on));b.textContent=on?'显示来源与结论':'隐藏来源与结论';if(on){f.value='all';filter()}f.disabled=on;document.querySelector('.stats').style.visibility=on?'hidden':'';document.querySelector('.method').style.visibility=on?'hidden':'';document.querySelector('table').style.visibility=on?'hidden':''});</script></body></html>'''
